    void init(MaterialRequestServicePort s, AppState a, Supplier<Long> c, Supplier<Window> o){init(s,null,a,null,null,null,c,o);} void init(MaterialRequestServicePort s, CaseTaskService tasks, AppState a, Supplier<Long> c, Supplier<Window> o){init(s,tasks,a,null,null,null,c,o);} void init(MaterialRequestServicePort s, CaseTaskService tasks, AppState a, CaseDao cd, ContactDao ctd, OrganizationDao od, Supplier<Long> c, Supplier<Window> o){svc=s;caseTaskService=tasks;state=a;caseDao=cd;contactDao=ctd;organizationDao=od;caseId=c;owner=o; rebuildRequestCardFactory();}
